preConditionHook:
// EL Time is the bar's closing time as HHMM (EL_FEATURES.md `time`,
// VERIFIED: exchange clock, wall-clock close, midnight reads 0), and
// Time[n] is ordinary series history. ctx.Time(n) is that same close
// timestamp, so HHMM is its seconds-of-day re-packed -- the TimeWindow
// derivation, evaluated for each of the last windowBars + 1 bars.
// The window is in BARS: converting HHMM to minutes would need EL's Mod
// (UNKNOWN) or IntPortion (unregistered).
isKeyTime = false;
for (int i = 0; i <= (int)windowBars; ++i) {
    barSeconds = seconds_of_day(ctx.Time(i));
    barHHMM = (barSeconds / 3600) * 100 + (barSeconds % 3600) / 60;
    if (el_eq((double)barHHMM, keyTime1) || el_eq((double)barHHMM, keyTime2)
        || el_eq((double)barHHMM, keyTime3)) {
        isKeyTime = true;
    }
}
